(* [comment removed for export] *)
Lemma fb_block_transport : forall W m m' (FB : fbv) (ds : list byte),
  (FB <> FB_empty -> exists pre junk,
      rw_cells usegs m (fb_begin FB) [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) junk]) ->
  munch W m m' -> wmono usegs m m' ->
  fb_begin FB <= fb_in FB -> zlength ds = fb_out FB - fb_in FB -> fb_out FB <= fb_end FB ->
  disjoint_from W (fb_begin FB) (fb_end FB - fb_begin FB) ->
  (FB <> FB_empty -> exists pre junk,
      rw_cells usegs m' (fb_begin FB) [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) junk]).
Proof.
  intros W m m' FB ds BLK MU WM H1 H2 H3 D NE. destruct (BLK NE) as (pre & junk & B). exists pre, junk.
  eapply rw_cells_transport; [exact B | exact MU | exact WM |].
  cbn [cells_size csize Nat.add]. unfold zlength in H2.
  replace (Z.of_nat (Z.to_nat (fb_in FB - fb_begin FB) + (length ds + (Z.to_nat (fb_end FB - fb_out FB) + 0))))
    with (fb_end FB - fb_begin FB) by lia.
  exact D.
Qed.

Lemma FlatBuf_of_parts : forall LB m a FB ds,
  rw_cells usegs m a (FlatBufCells FB) -> fb_ok LB FB -> zlength ds = fb_size FB ->
  (FB <> FB_empty -> exists pre junk,
      rw_cells usegs m (fb_begin FB) [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) junk]) ->
  FlatBuf LB m a FB ds.
Proof. intros. split; [assumption|]. split; [assumption|]. split; assumption. Qed.

