Lemma fb_block_src : forall m (FB : fbv) (ds pre bj : list byte) (k : nat),
  rw_cells usegs m (fb_begin FB) [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) bj] ->
  fb_begin FB <= fb_in FB -> (k <= length ds)%nat ->
  bytes_at usegs m (fb_in FB) (firstn k ds).
