Lemma rw_cells_join_CB : forall m A (n k : nat) (bs1 bs2 : list byte),
  rw_cells usegs m A [CB k bs1] -> rw_cells usegs m (A + Z.of_nat k) [CB n bs2] ->
  rw_cells usegs m A [CB k bs1; CB n bs2].
Proof.
