Definition memmove_le_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Dst N : Z) (src : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1' a2' a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 Dst) a1' a2' a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(Dst, Dst + N)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ rw_cells usegs m' Dst [CB (Z.to_nat N) src].

Definition memmove_le_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (Dst Src N : Z) (src junk : list byte),
  bytes_at usegs m Src src -> length src = Z.to_nat N ->
  rw_cells usegs m Dst [CB (Z.to_nat N) junk] ->
  Dst <= Src -> 0 <= N -> Src + N <= hceil ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (memmove_le_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Dst N src m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 Dst) (Z_to_bv 64 Src) (Z_to_bv 64 N) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_MEMMOVE) fc None m (seg_rom usegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)

Definition FB_PREPARE_STACK : Z := 112 + ROPNEW_STACK.
Definition FBP_RET1 : Z := 0x385ac.     (* [comment removed for export] *)
Definition FBP_RET2 : Z := 0x385d4.     (* [comment removed for export] *)

(* [comment removed for export] *)
Definition fb_prep_small (FB : fbv) (n : Z) : fbv :=
  if fb_prep_inplace FB n
  then mkFB (fb_begin FB) (fb_in FB) (fb_out FB) (fb_out FB + n) (fb_end FB)
  else mkFB (fb_begin FB) (fb_begin FB) (fb_begin FB + fb_size FB) (fb_begin FB + fb_size FB + n) (fb_end FB).
(* [comment removed for export] *)
Definition fb_prep_grow (FB : fbv) (n A' : Z) : fbv :=
  mkFB A' A' (A' + fb_size FB) (A' + fb_size FB + n) (A' + fb_newsize FB n).

(* [comment removed for export] *)
Definition fb_X (fb : Z) (FB : fbv) : list (Z * Z) := [(fb, fb + SZ_FB); (fb_begin FB, fb_end FB)].

Section SR.
  Variable H : hsr.

  (* [comment removed for export] *)
  Definition fb_prepare_rel (LB : list block) (FB : fbv) (n : Z) (LB' : list block) (FB' : fbv) : Prop :=
    if fb_prep_inplace FB n || fb_prep_slide FB n
    then FB' = fb_prep_small FB n /\ LB' = LB
    else exists (p' : bptr) (A' : Z),
           rblock_range A' (fb_newsize FB n) /\ FB' = fb_prep_grow FB n A'
        /\ ((FB = FB_empty /\ LB' = (p', A', fb_newsize FB n) :: LB)
            \/ (exists p, In (p, fb_begin FB, fb_cap FB) LB /\ LB' = (p', A', fb_newsize FB n) :: hs_lb_remove H p LB)).

Definition fb_prepare_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (fb n lo B : Z) (FB : fbv) (ds : list byte) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (LB' : list block) (FB' : fbv),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (fb_out FB')) (wz n) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m'
      /\ FlatBuf LB' m' fb FB' ds
      /\ fb_last FB' = fb_out FB' + n
      /\ fb_prepare_rel LB FB n LB' FB'
      /\ xpres LB (bv_unsigned sp) (fb_X fb FB) m m'.

  (* [comment removed for export] *)
  Definition fb_prepare_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (fb n lo B : Z) (FB : fbv) (ds : list byte) (errv : word),
      a0 = wz fb -> a1 = wz n ->
      FlatBuf LB m fb FB ds -> fb mod 8 = 0 ->
      0 <= n -> fb_cap FB + n < 2^30 ->
      rclient_range LB (bv_unsigned sp) fb SZ_FB -> rclient_write_ok LB (fb, fb + SZ_FB) -> fb + SZ_FB <= B ->
      (fb + SZ_FB <= fb_begin FB \/ fb_end FB <= fb) ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + fb_newsize FB n <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - FB_PREPARE_STACK ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (fb_prepare_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB fb n lo B FB ds m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_FB_PREPARE) fc None m (seg_rom usegs)) mo).

  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Definition DBP_STACK : Z := 64 + FB_PREPARE_STACK.
  Definition DBP_RET1 : Z := 0x3cd7c.

Definition dbp_fb_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (OPT fb n ec lo B : Z) (FB : fbv) (ds oj : list byte) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (LB' : list block) (FB' : fbv),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m'
      /\ FlatBuf LB' m' fb FB' ds
      /\ fb_last FB' = fb_out FB' + n
      /\ fb_prepare_rel LB FB n LB' FB'
      /\ rw_cells usegs m' OPT [CB 1 [b8 1]; CB 7 (firstn 7 (skipn 1 oj)); C8 (wz (fb_out FB')); C8 (wz n)]
      /\ rw_cells usegs m' ec (ErrCodeCells EC_clear)
      /\ xpres LB (bv_unsigned sp) ((OPT, OPT + 24) :: (ec, ec + 24) :: fb_X fb FB) m m'.

  Definition dbp_fb_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (OPT fb n ec lo B : Z) (FB : fbv) (ds oj : list byte) (E : ecv) (errv : word),
      a0 = wz OPT -> a1 = wz fb -> a2 = wz n -> a3 = wz ec ->
      (* [comment removed for export] *)
      rw_cells usegs m OPT [CB 24 oj] -> OPT mod 8 = 0 -> bv_unsigned sp <= OPT -> OPT + 24 <= B ->
      rw_cells usegs m ec (ErrCodeCells E) -> ec mod 8 = 0 -> bv_unsigned sp <= ec -> ec + 24 <= B ->
      (OPT + 24 <= ec \/ ec + 24 <= OPT) -> (OPT + 24 <= fb \/ fb + SZ_FB <= OPT) -> (ec + 24 <= fb \/ fb + SZ_FB <= ec) ->
      (* [comment removed for export] *)
      FlatBuf LB m fb FB ds -> fb mod 8 = 0 ->
      0 <= n -> fb_cap FB + n < 2^30 ->
      rclient_range LB (bv_unsigned sp) fb SZ_FB -> rclient_write_ok LB (fb, fb + SZ_FB) -> fb + SZ_FB <= B ->
      (fb + SZ_FB <= fb_begin FB \/ fb_end FB <= fb) ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + fb_newsize FB n <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - DBP_STACK ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (dbp_fb_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB OPT fb n ec lo B FB ds oj m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_FB_DYN_PREPARE) fc None m (seg_rom usegs)) mo).
End SR.

