(* [comment removed for export] *)
Ltac side := first [ eassumption
                   | rewrite ?unsigned_lit by lia; first [ eassumption | reflexivity | lia ]
                   | lia ].

(* [comment removed for export] *)
Ltac eq_leaves tac :=
  repeat first [ reflexivity
               | lazymatch goal with |- @eq Z _ _ => tac | _ => f_equal end ].
Ltac finish_core tac :=
  hnf;
  repeat (lazymatch goal with |- ex _ => eexists end);
  repeat (lazymatch goal with |- ?A /\ _ => lazymatch A with _ = MS _ _ _ _ _ _ _ => fail | _ => split; [tac|] end end);
  lazymatch goal with
  | |- _ = _ /\ _ => split; [ cbv delta [mkR]; eq_leaves tac | ]
  | |- _ = _ => cbv delta [mkR]; eq_leaves tac
  end;
  repeat match goal with |- _ /\ _ => split end; try assumption.
Ltac finish_with tac :=
  apply evt_done;
  lazymatch goal with |- ?P ?ms => try unfold P end; cbv beta;
  finish_core tac.
Ltac finish_left tac := apply evt_done; lazymatch goal with |- ?P ?ms => try unfold P end; cbv beta; left; finish_core tac.
Ltac finish_right tac := apply evt_done; lazymatch goal with |- ?P ?ms => try unfold P end; cbv beta; right; finish_core tac.

Definition hidden (P : Prop) : Prop := P.
Lemma hide : forall P : Prop, P -> hidden P. Proof. exact (fun P p => p). Qed.
Ltac hideH H := apply hide in H.
Ltac showH H := unfold hidden in H.


