Lemma nullbase_xor : forall b s, (0 < b /\ 0 < s) \/ (b = 0 /\ s = 0) -> Z.lxor (Z.b2z (0 <? b)) (Z.b2z (s <? 1)) = 1.
Proof.
  intros b s Hb. destruct (Z.ltb_spec 0 b); destruct (Z.ltb_spec s 1); cbn; first [reflexivity | exfalso; lia].
Qed.

(* [comment removed for export] *)
Definition fbp_seg2_post (sp gp tp s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (fb n A' ns : Z) (FB : fbv) (ds junkA : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' a0' a1' : word) (pc' : Z) t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 (Z_to_bv 64 n) (Z_to_bv 64 fb) a0' a1' a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb_begin FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 ns) (Z_to_bv 64 A')
                  (Z_to_bv 64 (fb_cap FB)) s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 pc') fc None m' (seg_rom usegs)
    /\ munch [(A', A' + fb_size FB)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ rw_cells usegs m' A' [CB (Z.to_nat (fb_size FB)) ds; CB (Z.to_nat (ns - fb_size FB)) (skipn (Z.to_nat (fb_size FB)) junkA)]
    /\ ((FB = FB_empty /\ pc' = FBP_RET2)
        \/ (FB <> FB_empty /\ pc' = ROPDEL2 /\ ra' = Z_to_bv 64 FBP_RET2
            /\ a0' = Z_to_bv 64 (fb_begin FB) /\ a1' = Z_to_bv 64 (fb_cap FB))).
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

Lemma fbp_seg2 : forall (fb n A' ns : Z) (LB : list block) (FB : fbv) (ds junkA : list byte)
    ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s6 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  FlatBuf LB m fb FB ds ->
  0 <= n -> fb_cap FB + n < 2^30 -> fb_size FB + n <= ns -> ns < 2^31 ->
  rw_cells usegs m A' [CB (Z.to_nat ns) junkA] -> 0 < A' -> A' + ns <= hceil ->
  (A' + ns <= fb_begin FB \/ fb_end FB <= A') ->
  mem_inv usegs m ->
  evt usegs (fbp_seg2_post sp gp tp s8 s9 s10 s11 F fc fb n A' ns FB ds junkA m)
    (MS (mkR ra sp gp tp t0 t1 t2 (Z_to_bv 64 n) (Z_to_bv 64 fb) (Z_to_bv 64 A') a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb_begin FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 ns) s6 (Z_to_bv 64 (fb_cap FB))
              s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 FBP_RET1) fc None m (seg_rom usegs)).
