(* [comment removed for export] *)
Section SEG1.
  Hypothesis MMV : memmove_le_stmt.

  Definition fbp_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (LB : list block) (fb n lo : Z) (FB : fbv) (ds : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' =>
      (exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
          fb_prep_inplace FB n || fb_prep_slide FB n = true
          /\ ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (fb_out (fb_prep_small FB n))) (Z_to_bv 64 n) a2 a3 a4 a5 a6 a7
                       s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (ret_pc ra) fc None m' (seg_rom usegs)
          /\ munch [(lo, bv_unsigned sp); (fb, fb + SZ_FB); (fb_begin FB, fb_end FB)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
          /\ stk usegs m' lo (bv_unsigned sp)
          /\ FlatBuf LB m' fb (fb_prep_small FB n) ds)
      \/ (exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' fj,
          fb_prep_inplace FB n = false /\ fb_prep_slide FB n = false
          /\ ms' = MS (mkR (Z_to_bv 64 FBP_RET1) (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2
                       (Z_to_bv 64 n) (Z_to_bv 64 fb) (Z_to_bv 64 (fb_newsize FB n)) a1 a2 a3 a4 a5 a6 a7
                       (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb_begin FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 (fb_newsize FB n))
                       s6 (Z_to_bv 64 (fb_cap FB)) s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 ROPNEW) fc None m' (seg_rom usegs)
          /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
          /\ stk usegs m' lo (bv_unsigned sp + -112)
          /\ rw_cells usegs m' (bv_unsigned sp + -112) (fbp_frame fj s7 s6 s5 s4 s3 s2 s1 s0 ra)
          /\ FlatBuf LB m' fb FB ds).

  Lemma fbp_seg1 : forall (fb n lo : Z) (LB : list block) (FB : fbv) (ds : list byte)
      ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem),
    FlatBuf LB m fb FB ds -> fb mod 8 = 0 ->
    0 <= n -> fb_cap FB + n < 2^30 ->
    stk usegs m lo (bv_unsigned sp) -> lo + 112 <= bv_unsigned sp -> hceil <= lo ->
    (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) ->
    (fb + SZ_FB <= fb_begin FB \/ fb_end FB <= fb) ->
    bv_unsigned ra mod 2 = 0 ->
